import React from "react";
import { Building2, FileText, ShieldCheck, Users } from "lucide-react";
import { DashboardLayout } from "../components/layout/DashboardLayout";
import { useAuth } from "../contexts/AuthContext";

const StatCard = ({ icon: Icon, label, value, color }) => (
  <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-5 flex items-center gap-4">
    <div className={`p-3 rounded-lg ${color}`}>
      <Icon className="w-6 h-6 text-white" />
    </div>
    <div>
      <p className="text-2xl font-bold text-gray-900">{value}</p>
      <p className="text-sm text-gray-500">{label}</p>
    </div>
  </div>
);

// Descripción de bienvenida según los permisos/alcance del rol del usuario,
// sin depender de nombres de rol fijos.
const getWelcomeDescription = (user, hasPermission) => {
  if (hasPermission("roles.manage")) {
    return "Tienes acceso total al sistema: empresas, usuarios, roles y toda la gestión documental.";
  }
  if (!user?.role?.is_company_scoped) {
    return "Tienes visión transversal del cumplimiento documental de todas las empresas.";
  }
  return "Aquí verás únicamente las empresas que tienes asignadas y su documentación.";
};

export const DashboardPage = () => {
  const { user, hasPermission } = useAuth();

  return (
    <DashboardLayout>
      <div className="mb-6">
        <h2 className="text-xl sm:text-2xl font-bold text-gray-900">
          Hola, {user?.full_name?.split(" ")[0] || "bienvenido"} 👋
        </h2>
        <p className="text-sm sm:text-base text-gray-600 mt-1">
          {getWelcomeDescription(user, hasPermission)}
        </p>
        <span className="inline-block mt-2 text-xs font-semibold uppercase tracking-wide bg-green-100 text-green-700 px-2.5 py-1 rounded-full">
          {user?.role?.name}
        </span>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard icon={Building2} label="Empresas" value="—" color="bg-blue-500" />
        <StatCard icon={FileText} label="Documentos" value="—" color="bg-green-600" />
        <StatCard icon={ShieldCheck} label="Cumplimiento" value="—" color="bg-emerald-500" />
        <StatCard icon={Users} label="Usuarios" value="—" color="bg-teal-600" />
      </div>

      <div className="mt-8 bg-white rounded-xl shadow-sm border border-gray-100 p-6 text-center">
        <FileText className="w-10 h-10 text-green-600 mx-auto mb-3" />
        <h3 className="text-base sm:text-lg font-bold text-gray-900">
          Próximamente: Gestión Documental
        </h3>
        <p className="text-sm text-gray-500 mt-1 max-w-md mx-auto">
          Aquí se mostrará el catálogo de documentos de SST, su estado de
          cumplimiento por empresa y las fechas de vencimiento.
        </p>
      </div>
    </DashboardLayout>
  );
};

export default DashboardPage;
